(s) => {
  const a = s["checks$answers"].answers;
  const p = {
    registry: a.registry_status.choice, registry_confidence: a.registry_status.confidence,
    does_this_business: a.does_this_business.noul, adverse_news: a.adverse_news.noul
  };
  const reject = [], review = [];
  if (p.registry === "not_found" && p.registry_confidence >= 0.7) reject.push("no registry record in " + s.state + " (confidence " + p.registry_confidence.toFixed(2) + ")");
  else if (p.registry !== "active" || p.registry_confidence < 0.7) review.push("registry status " + p.registry + " (confidence " + p.registry_confidence.toFixed(2) + ")");
  if (p.adverse_news >= 0.7) reject.push("adverse news (P(yes) " + p.adverse_news.toFixed(2) + ")");
  else if (p.adverse_news >= 0.3) review.push("possible adverse news (P(yes) " + p.adverse_news.toFixed(2) + ")");
  if (p.does_this_business < 0.7) review.push("the business is not confirmed (P(yes) " + p.does_this_business.toFixed(2) + ")");
  const evidence = (s["checks$answers"].evidence || []).map((e) => e.url);
  const reasons = reject.concat(review);
  return { action: reject.length ? "reject" : review.length ? "review" : "approve", reasons, reasons_text: reasons.join("; "), probabilities: p, evidence };
}
